abel><input id="uiDensity" type="range" min="500" max="6000" step="500" value="2000"><span class="cap" id="capDensity">2000</span></div> <div class="row"><label>Speed</label><input id="uiSpeed" type="range" min="0.5" max="4" step="0.1" value="1.6"><span class="cap" id="capSpeed">1.6×</span></div> <div class="row"><label>Vertical Fill</label><input id="uiVertical" type="range" min="0.8" max="3" step="0.1" value="1.6"><span class="cap" id="capVertical">1.6×</span></div> <div class="row"><label>Tail Amp</label><input id="uiTailAmp" type="range" min="0" max="0.6" step="0.02" value="0.25"><span class="cap" id="capTailAmp">0.25</span></div> <div class="row"><label>Tail Freq</label><input id="uiTailFreq" type="range" min="1" max="12" step="0.5" value="6"><span class="cap" id="capTailFreq">6.0 Hz</span></div> <div class="row"><label>Band Count</label><input id="uiBands" type="range" min="1" max="10" step="1" value="5"><span class="cap" id="capBands">5</span></div> <div class="row"><label>Color Jitter</label><input id="uiJitter" type="range" min="0" max="0.5" step="0.01" value="0.12"><span class="cap" id="capJitter">0.12</span></div> <div class="row"><label>Palette</label> <select id="uiPalette"> <option value="natural" selected>Natural Blues</option> <option value="neon">Neon (Cyan/Magenta)</option> <option value="sunset">Sunset (Amber/Teal)</option> </select> <span></span> </div> </div> <div class="bar"> <button data-preset="calm">Calm</button> <button data-preset="murmur">Murmuration</button> <button data-preset="storm">Storm</button> <button data-preset="columns">Columns</button> </div> <div id="tests"></div> </div> <script type="module"> import * as THREE from 'https://cdn.skypack.dev/three@0.128.0/build/three.module.js'; import { OrbitControls } from 'https://cdn.skypack.dev/three@0.128.0/examples/jsm/controls/OrbitControls.js'; import { AnaglyphEffect } from 'https://cdn.skypack.dev/three@0.128.0/examples/jsm/effects/AnaglyphEffect.js'; let scene, camera, renderer, effect, controls, instancedMesh, fishMaterial; let useAnaglyph = false; let animationMode = 7; // default to murmuration let INSTANCED_COUNT = 2000; // UI-adjustable const params = { speed: 1.6, vertical: 1.6, tailAmp: 0.25, tailFreq: 6.0, bands: 5, jitter: 0.12, palette: 'natural' }; const dummy = new THREE.Object3D(); let basePositions = []; let instancePhaseAttr = null; let instanceHueAttr = null; // per-instance hue 0..1 let instanceBandAttr = null; // per-instance band index 0..1 normalized /* --------------------------- Geometry helpers --------------------------- */ function mergeGeometriesSimple(geos) { const positions = []; for (const g of geos) { const gg = g.index ? g.toNonIndexed() : g; positions.push(gg.getAttribute('position').array); } const total = positions.reduce((n, a) => n + a.length, 0); const mergedPos = new Float32Array(total); let offset = 0; for (const arr of positions) { mergedPos.set(arr, offset); offset += arr.length; } const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.Float32BufferAttribute(mergedPos, 3)); geo.computeVertexNormals(); return geo; } function buildFishGeometry() { const body = new THREE.SphereGeometry(0.25, 16, 12); body.applyMatrix4(new THREE.Matrix4().makeScale(1.8, 0.9, 4.0)); const tail = new THREE.ConeGeometry(0.5, 1.2, 12); tail.rotateX(Math.PI / 2); tail.applyMatrix4(new THREE.Matrix4().makeTranslation(0,0,-2.6)); tail.applyMatrix4(new THREE.Matrix4().makeScale(0.6,0.2,1.0)); const dorsal = new THREE.ConeGeometry(0.35, 0.6, 8); dorsal.applyMatrix4(new THREE.Matrix4().makeRotationX(Math.PI)); dorsal.applyMatrix4(new THREE.Matrix4().makeTranslation(0,0.6,0.2)); dorsal.applyMatrix4(new THREE.Matrix4().makeScale(1.0,0.6,0.6)); const fin = new THREE.BoxGeometry(0.6, 0.08, 0.35); fin.applyMatrix4(new THREE.Matrix4().makeTranslation(0.45,-0.05,0.0)); const finL = fin.clone(); const finR = fin.clone(); finR.applyMatrix4(new THREE.Matrix4().makeScale(-1,1,1)); const fish = mergeGeometriesSimple([body, tail, dorsal, finL, finR]); fish.computeBoundingSphere(); return fish; } /* ----------------------------- Material (shader tweaks) ----------------------------- */ function createFishMaterial() { const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, metalness: 0.1, roughness: 0.55 }); mat.onBeforeCompile = (shader) => { // uniforms shader.uniforms.uTime = { value: 0 }; shader.uniforms.uTailAmp = { value: params.tailAmp }; shader.uniforms.uTailFreq = { value: params.tailFreq }; shader.uniforms.uBands = { value: Math.max(1, params.bands) }; shader.uniforms.uJitter = { value: params.jitter }; shader.uniforms.uPalette = { value: paletteIndex(params.palette) }; // attributes -> varyings shader.vertexShader = 
attribute float instancePhase;
attribute float instanceHue;
attribute float instanceBand;
varying float vHue;
varying float vBand;
uniform float uTime;
uniform float uTailAmp;
