 + shader.vertexShader; shader.vertexShader = shader.vertexShader.replace( '#include <begin_vertex>', #include <begin_vertex>
 // Tail wag weighted toward negative Z (the tail)
 float tail = clamp((-transformed.z - 0.5) / 2.0, 0.0, 1.0);
 float sway = sin(uTime * uTailFreq + instancePhase) * uTailAmp * tail;
 transformed.x += sway;
 vHue = instanceHue;
 vBand = instanceBand;
 ); // HSV helpers + palette const fragPreamble = 
vec3 hsv2rgb(vec3 c){
 vec4 K = vec4(1.0, 2.0/3.0, 1.0/3.0, 3.0);
 vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
 return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
vec3 paletteColor(int idx, float t){
 if(idx==0){ // natural blues return mix(vec3(0.50,0.70,1.00), vec3(0.25,0.55,0.95), t);
 } else if(idx==1){ // neon return mix(vec3(0.00,1.00,1.00), vec3(1.00,0.20,1.00), t);
 } else { // sunset return mix(vec3(1.00,0.55,0.20), vec3(0.10,0.70,0.70), t);
 }
}
; shader.fragmentShader = 
varying float vHue;
varying float vBand;
uniform float uBands;
uniform float uJitter;
uniform int uPalette;
 + fragPreamble + shader.fragmentShader; shader.fragmentShader = shader.fragmentShader.replace( '#include <color_fragment>', #include <color_fragment>
 // Per-instance palette mix: banded groups + jittered hue shift
 float bandIdx = floor(vBand * uBands + 1e-5);
 float t = (uBands <= 1.0) ? 0.5 : bandIdx / max(1.0, uBands - 1.0);
 vec3 baseCol = paletteColor(uPalette, t);
 float hShift = (vHue - 0.5) * 2.0 * uJitter; // +/- jitter vec3 jitterCol = hsv2rgb(vec3(fract(hShift + 0.6), 0.55, 1.0));
 diffuseColor.rgb *= mix(baseCol, jitterCol, uJitter*0.6);
 ); mat.userData.shader = shader; }; return mat; } function paletteIndex(name){ return name==='neon'?1:(name==='sunset'?2:0); } /* ---------------------------------- Setup ---------------------------------- */ function init() { scene = new THREE.Scene(); camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000); camera.position.set(0, 6, 18); renderer = new THREE.WebGLRenderer({ antialias: true }); renderer.setPixelRatio(Math.min(2, window.devicePixelRatio)); renderer.setSize(window.innerWidth, window.innerHeight); renderer.shadowMap.enabled = false; // perf first document.body.appendChild(renderer.domElement); effect = new AnaglyphEffect(renderer); effect.setSize(window.innerWidth, window.innerHeight); controls = new OrbitControls(camera, renderer.domElement); controls.target.set(0,3,0); controls.update(); scene.add(new THREE.HemisphereLight(0x9acbff, 0x2a1b0b, 0.9)); const dir = new THREE.DirectionalLight(0xffffff, 0.6); dir.position.set(10,20,10); scene.add(dir); fishMaterial = createFishMaterial(); rebuildSchool(INSTANCED_COUNT); wireUI(); window.addEventListener('resize', onWindowResize); window.addEventListener('keydown', onKeyDown); runSelfTests(); animate(0); } function rebuildSchool(count){ if (instancedMesh){ scene.remove(instancedMesh); instancedMesh.geometry.dispose(); instancedMesh.material.dispose(); } INSTANCED_COUNT = count; basePositions = new Array(INSTANCED_COUNT); const fishGeo = buildFishGeometry(); instancedMesh = new THREE.InstancedMesh(fishGeo, fishMaterial = createFishMaterial(), INSTANCED_COUNT); instancedMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage); // per-instance attributes const phases = new Float32Array(INSTANCED_COUNT); const hues = new Float32Array(INSTANCED_COUNT); const bands = new Float32Array(INSTANCED_COUNT); for (let i=0;i<INSTANCED_COUNT;i++){ phases[i] = Math.random()*Math.PI*2.0; hues[i] = Math.random(); bands[i] = (i % Math.max(1, params.bands)) / Math.max(1, params.bands-1); } instancePhaseAttr = new THREE.InstancedBufferAttribute(phases, 1); instancedMesh.geometry.setAttribute('instancePhase', instancePhaseAttr); instanceHueAttr = new THREE.InstancedBufferAttribute(hues, 1); instancedMesh.geometry.setAttribute('instanceHue', instanceHueAttr); instanceBandAttr = new THREE.InstancedBufferAttribute(bands, 1); instancedMesh.geometry.setAttribute('instanceBand', instanceBandAttr); for (let i=0;i<INSTANCED_COUNT;i++){ const px = Math.random()*40 - 20; const py = Math.random()*10 + 1.5; const pz = Math.random()*40 - 20; basePositions[i] = new THREE.Vector3(px,py,pz); dummy.position.set(px,py,pz); dummy.quaternion.identity(); dummy.updateMatrix(); instancedMesh.setMatrixAt(i, dummy.matrix); } instancedMesh.instanceMatrix.needsUpdate = true; scene.add(instancedMesh); } /* --------------------------------- UI --------------------------------- */ function wireUI(){ const D = (id)=>document.getElementById(id); const d=D('uiDensity'), s=D('uiSpeed'), v=D('uiVertical'), a=D('uiTailAmp'), f=D('uiTailFreq'), b=D('uiBands'), j=D('uiJitter'), p=D('uiPalette'); const cd=D('capDensity'), cs=D('capSpeed'), cv=D('capVertical'), ca=D('capTailAmp'), cf=D('capTailFreq'), cb=D('capBands'), cj=D('capJitter'); d.addEventListener('input', ()=>cd.textContent=d.value); d.addEventListener('change', ()=>rebuildSchool(parseInt(d.value,10))); s.addEventListener('input', ()=>{ params.speed=parseFloat(s.value); cs.textContent=${params.speed.toFixed(1)}×; }); v.addEventListener('input', ()=>{ params.vertical=parseFloat(v.value); cv.textContent=${params.vertical.toFixed(1)}×; }); a.addEventListener('input', ()=>{ params.tailAmp=parseFloat(a.value); ca.textContent=params.tailAmp.toFixed(2); updateShaderUniforms(); }); f.addEventListener('input', ()=>{ params.tailFreq=parseFloat(f.value); cf.textContent=${params.tailFreq.toFixed(1)} Hz; updateShaderUniforms(); }); b.addEventListener('input', ()=>{ params.bands=parseInt(b.value,10); cb.textContent=params.bands; updateShaderUniforms(); rebuildBands(); }); j.addEventListener('input', ()=>{ params.jitter=parseFloat(j.value); cj.textContent=params.jitter.toFixed(2); updateShaderUniforms(); }); p.addEventListener('change', ()=>{ params.palette=p.value; updateShaderUniforms(); }); // Presets document.querySelectorAll('button[data-preset]').forEach(btn=>btn.addEventListener('click',()=>applyPreset(btn.dataset.preset))); } function updateShaderUniforms(){ if (fishMaterial && fishMaterial.userData && fishMaterial.userData.shader){ const u = fishMaterial.userData.shader.uniforms; u.uTailAmp.value = params.tailAmp; u.uTailFreq.value = params.tailFreq; u.uBands.value = Math.max(1, params.bands); u.uJitter.value = params.jitter; u.uPalette.value = paletteIndex(params.palette); } } function rebuildBands(){ if (!instanceBandAttr) return; for (let i=0;i<INSTANCED_COUNT;i++) instanceBandAttr.array[i] = (i % Math.max(1, params.bands)) / Math.max(1, params.bands-1); instanceBandAttr.needsUpdate = true; } function applyPreset(name){ const presets = { calm: { mode:2, density:1500, speed:1.0, vertical:1.2, tailAmp:0.18, tailFreq:4.5, bands:4, jitter:0.06, palette:'natural' }, murmur: { mode:7, density:2500, speed:1.6, vertical:1.6, tailAmp:0.25, tailFreq:6.0, bands:5, jitter:0.12, palette:'natural' }, storm: { mode:9, density:3500, speed:2.6, vertical:2.2, tailAmp:0.32, tailFreq:8.0, bands:6, jitter:0.18, palette:'neon' }, columns: { mode:8, density:2200, speed:1.8, vertical:2.4, tailAmp:0.28, tailFreq:7.0, bands:5, jitter:0.10, palette:'sunset' }, }; const p = presets[name]; if (!p) return; animationMode = p.mode; const D=(id)=>document.getElementById(id); D('uiDensity').value=p.density; D('capDensity').textContent=p.density; rebuildSchool(p.density); D('uiSpeed').value=p.speed; params.speed=p.speed; D('capSpeed').textContent=${p.speed.toFixed(1)}×; D('uiVertical').value=p.vertical; params.vertical=p.vertical; D('capVertical').textContent=${p.vertical.toFixed(1)}×; D('uiTailAmp').value=p.tailAmp; params.tailAmp=p.tailAmp; D('capTailAmp').textContent=p.tailAmp.toFixed(2); D('uiTailFreq').value=p.tailFreq; params.tailFreq=p.tailFreq; D('capTailFreq').textContent=${p.tailFreq.toFixed(1)} Hz; D('uiBands').value=p.bands; params.bands=p.bands; D('capBands').textContent=p.bands; D('uiJitter').value=p.jitter; params.jitter=p.jitter; D('capJitter').textContent=p.jitter.toFixed(2); D('uiPalette').value=p.palette; params.palette=p.palette; updateShaderUniforms(); rebuildBands(); document.getElementById('mode').innerHTML = Mode: <strong>${animationMode} (${['—','Wave','School','Lissajous','Flow‑Field','Torus‑Knot','Vortex‑School','Murmuration','Columns','Turbulence'][animationMode]})</strong>; } /* ------------------------------ Events ------------------------------ */ function onWindowResize(){ camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize(window.innerWidth, window.innerHeight); effect.setSize(window.innerWidth, window.innerHeight); } function onKeyDown(e){ const k=e.key.toLowerCase(); if(k==='a') useAnaglyph=!useAnaglyph; else if(k>='1'&&k<='9'){ animationMode=parseInt(k,10); const names=['—','Wave','School','Lissajous','Flow‑Field','Torus‑Knot','Vortex‑School','Murmuration','Columns','Turbulence']; document.getElementById('mode').innerHTML=Mode: <strong>${animationMode} (${names[animationMode]})</strong>; } } /* ------------------------------ Motion ------------------------------ */ function evalPosition(i, t){ const speedT = t * params.speed; const cx=Math.sin(speedT*0.20)*4.0; const cz=Math.cos(speedT*0.25)*4.0; const ti=speedT + i*0.01; const base=basePositions[i]; let x=0,y=0,z=0; if (animationMode===1){ x=Math.cos(ti*0.5)*10+(i%20)*0.3; y=Math.sin(ti*2.0)*3+3; z=Math.sin(ti*0.5)*10+Math.floor(i/20)*0.3; } else if(animationMode===2){ const ang = ti + Math.sin(i*0.1); x=Math.sin(ang)*(10+Math.sin(speedT*0.5)*5); y=Math.sin(ang*2)+Math.cos(i*0.5)*2+2.5; z=Math.cos(ang)*(10+Math.cos(speedT*0.5)*5); } else if(animationMode===3){ const a=3,b=2,c=4; x=Math.sin(a*ti+i)*8; y=Math.cos(b*ti+i*0.5)*4+1.5; z=Math.sin(c*ti+i*0.3)*8; } else if(animationMode===4){ const fx=Math.sin(base.y*0.15+speedT*0.9)+Math.cos(base.z*0.11-speedT*0.6); const fy=Math.sin(base.z*0.17+speedT*0.7)+Math.cos(base.x*0.09+speedT*0.8); const fz=Math.sin(base.x*0.13-speedT*0.5)+Math.cos(base.y*0.07+speedT*0.4); const amp=4.0; x=base.x+fx*amp; y=Math.max(0.5, base.y+fy*(amp*0.5)*params.vertical); z=base.z+fz*amp; } else if(animationMode===5){ const p=2,q=3; const u=ti*1.2+(i*0.002); const R=7.0,r=2.5; x=(R + r*Math.cos(q*u))*Math.cos(p*u); y=(R + r*Math.cos(q*u))*Math.sin(p*u)*0.6 + 1.0; z=r*Math.sin(q*u); } else if(animationMode===6){ const rad=6.0+3.0*Math.sin(i*0.13+speedT*0.8); const ang=ti*(1.8+0.6*Math.sin(i*0.21))+Math.sin(i*0.37+speedT*1.2)*0.6; x=cx+Math.cos(ang)*rad; y=2.0+Math.sin(ang*2.3+i*0.01)*2.2 + Math.sin(speedT*3.0+i)*0.2; z=cz+Math.sin(ang)*rad; } else if(animationMode===7){ const layer=(i%50)/50; const r=4.0+6.0*layer+Math.sin(i*0.07+speedT*2.0)*(1.0+layer); const theta=ti*(2.5+layer*1.5)+Math.sin(i*0.11)*0.5; const phi=Math.sin(ti*1.9+i*0.031)*(Math.PI*0.35)+0.6; const burst=Math.sin(speedT*2.7+i*0.017); const jitter=0.8+Math.abs(burst)*0.7; const rr=r*jitter; const sx=Math.cos(theta)*Math.cos(phi); const sy=Math.sin(phi); const sz=Math.sin(theta)*Math.cos(phi); x=cx+sx*rr; y=3.0+sy*rr*(0.9*params.vertical); z=cz+sz*rr; } else if(animationMode===8){ const bands=5; const band=i%bands; const baseR=3.0+band*1.3; const height=12.0+Math.sin(speedT*1.5+band)*5.0; const theta=ti*(3.6+band*0.4)+Math.sin(i*0.09)*0.3; const yPulse=Math.sin(speedT*3.2+i*0.05)*1.1 + (band/(bands-1))*height - height*0.5; const rBreath=baseR*(1.0+0.35*Math.sin(speedT*2.0+band+i*0.02)); x=cx+Math.cos(theta)*rBreath; y=yPulse*params.vertical; z=cz+Math.sin(theta)*rBreath; } else { const nx=Math.sin((base.x+speedT*4.0)*0.6)+Math.cos((base.y-speedT*3.1)*0.7); const ny=Math.sin((base.y+speedT*3.7)*0.5)-Math.cos((base.z+speedT*4.2)*0.6); const nz=Math.cos((base.z-speedT*3.3)*0.5)-Math.sin((base.x+speedT*4.6)*0.7); const scale=8.0; x=cx+nx*scale; y=3.0+ny*(scale*1.3*params.vertical); z=cz+nz*scale; } return new THREE.Vector3(x,y,z); } function updateInstances(time){ const t = time * 0.001; const dt=0.02; for(let i=0;i<INSTANCED_COUNT;i++){ const p=evalPosition(i,t); const f=evalPosition(i,t+dt); const dir=f.sub(p); if(dir.lengthSq()<1e-6) dir.set(0,0,1); dir.normalize(); dummy.position.copy(p); dummy.lookAt(p.clone().add(dir)); dummy.rotateY(Math.PI); // +Z forward const side=new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0,1,0)).length(); dummy.rotateZ((Math.random()*0.04 - 0.02) + side*0.1); dummy.updateMatrix(); instancedMesh.setMatrixAt(i, dummy.matrix); } instancedMesh.instanceMatrix.needsUpdate = true; } /* ------------------------------ Loop ------------------------------ */ function animate(time){ requestAnimationFrame(animate); updateInstances(time); if (fishMaterial&&fishMaterial.userData&&fishMaterial.userData.shader){ const u=fishMaterial.userData.shader.uniforms; u.uTime.value = time*0.001*params.speed; } if (useAnaglyph) effect.render(scene, camera); else renderer.render(scene, camera); } /* --------------------------- Tests (overlay) --------------------------- */ function runSelfTests(){ const out=[]; try{ out.push(pass(Instances: ${INSTANCED_COUNT})); out.push(assert(!!instancedMesh && instancedMesh.count===INSTANCED_COUNT, 'instancedMesh count ok')); instancedMesh.instanceMatrix.needsUpdate=false; updateInstances(0); out.push(assert(instancedMesh.instanceMatrix.needsUpdate===true, 'needsUpdate flips after update')); const m=new THREE.Matrix4(); const p0=evalPosition(0,0); const p1=evalPosition(0,0.02); const disp=p1.clone().sub(p0).normalize(); instancedMesh.getMatrixAt(0,m); const o=new THREE.Vector3().setFromMatrixPosition(m); const fwd=new THREE.Vector3(0,0,1).applyMatrix4(m).sub(o).normalize(); out.push(assert(disp.dot(fwd)>0.4,'fish face motion')); }catch(e){ out.push(<span style="color:#ff8080">FAIL: ${e.message}</span>); console.error(e);} document.getElementById('tests').innerHTML = <strong>Self‑tests:</strong><br/>${out.join('<br/>')}; } function assert(c,m){ if(!c) throw new Error(m); return <span style='color:#9be29b'>PASS</span> ${m};} function pass(m){ return <span style='color:#9be29b'>PASS</span> ${m}; } // Boot init(); </script> </body> </html>"

