const ControlRow: React.FC<{
    label: string;
    value: number;
    min: number;
    max: number;
    step: number;
    suffix?: string;
    onChange: (val: string) => void;
    isEditing: boolean;
    setEditing: (isEd: boolean) => void;
}> = ({ label, value, min, max, step, suffix = "", onChange, isEditing, setEditing }) => {

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
        let val = parseFloat(e.target.value);
        if (isNaN(val)) val = value;
        // Clamp
        val = Math.max(min, Math.min(max, val));
        onChange(val.toString());
        setEditing(false);
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if(e.key === 'Enter') {
            (e.target as HTMLInputElement).blur();
        }
    };

    return (
        <div className="flex flex-col gap-1.5">
            <div className="flex justify-between items-end">
                <label className="text-xs text-white/60 font-medium">{label}</label>
                {isEditing ? (
                     <input 
                        type="number" 
                        autoFocus
                        defaultValue={value}
                        onBlur={handleBlur}
                        onKeyDown={handleKeyDown}
                        className="w-16 text-xs text-sky-200 font-mono bg-sky-900/30 px-1.5 py-0.5 rounded border border-sky-500/50 outline-none"
                    />
                ) : (
                    <span 
                        onClick={() => setEditing(true)}
                        className="text-xs text-sky-200 font-mono bg-sky-900/30 px-1.5 rounded cursor-text hover:bg-sky-800/50 transition-colors"
                    >
                        {value.toFixed(step < 0.1 ? 2 : 1)}{suffix}
                    </span>
                )}
            </div>
            <input 
                type="range" 
                min={min} 
                max={max} 
                step={step} 
                value={value} 
                onChange={(e) => onChange(e.target.value)}
                className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-sky-400 hover:accent-sky-300"
            />
        </div>
    );
};

export default ControlPanel;

import React, { useRef, useMemo, useLayoutEffect, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { useXR } from '@react-three/xr';
import * as THREE from 'three';
import { SimulationParams } from '../types';
import { buildFishGeometry } from './geometry';
import { evalPosition } from './mathUtils';
import { createFishMaterial } from './FishMaterial';

interface FishSchoolProps {
  params: SimulationParams;
}

// --- Ripple Shader Material ---
const RIPPLE_VERTEX = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const RIPPLE_FRAGMENT = `
  uniform float uTime;
  uniform vec3 uColor;
  varying vec2 vUv;

  void main() {
    vec2 center = vec2(0.5);
    float dist = distance(vUv, center);

    // 1. Primary Interference Pattern (High Frequency)
    // Simulates digital/holographic ripples
    float wave1 = sin(dist * 50.0 - uTime * 5.0);
    wave1 = smoothstep(0.9, 0.95, wave1); // Sharpen to thin lines

    // 2. Secondary Wave (Low Frequency) for organic feel
    float wave2 = sin(dist * 20.0 - uTime * 3.0);

    // 3. Caustic/sparkle effect
    float sparkle = sin(dist * 80.0 + uTime * 8.0) * 0.5 + 0.5;

    // 4. Radial Mask (Soft fade out)
    float mask = 1.0 - smoothstep(0.0, 0.5, dist);

    // Combine
    float combined = (wave1 * 0.6 + wave2 * 0.2 + sparkle * 0.1) * mask;

    // Pulse intensity (Breathing effect)
    float pulse = 0.6 + 0.2 * sin(uTime * 2.0);

    // Mix color with white highlights on peaks
    vec3 finalColor = mix(uColor, vec3(1.0), wave1 * 0.6);

    gl_FragColor = vec4(finalColor, combined * pulse * 0.6); // Subtly transparent
  }
`;

const FishSchool: React.FC<FishSchoolProps> = ({ params }) => {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const rippleRef = useRef<THREE.Mesh>(null);
  const rippleMatRef = useRef<THREE.ShaderMaterial>(null);
  const handVisualRef = useRef<THREE.Mesh>(null);

  const { raycaster, pointer, camera } = useThree();
  const { isPresent, controllers } = useXR(); // WebXR Hooks

  // Create geometry once
  const geometry = useMemo(() => buildFishGeometry(), []);

  // Prepare Base Positions & Attributes
  const { basePositions, phases, hues, bands } = useMemo(() => {
    const count = params.density;
    const basePos = new Array(count);
    const ph = new Float32Array(count);
    const hu = new Float32Array(count);
    const ba = new Float32Array(count);

    for (let i = 0; i < count; i++) {
      // Random Base Pos
      const px = Math.random() * 40 - 20;
      const py = Math.random() * 10 + 1.5;
      const pz = Math.random() * 40 - 20;
      basePos[i] = new THREE.Vector3(px, py, pz);

      // Attributes
      ph[i] = Math.random() * Math.PI * 2.0;
      hu[i] = Math.random();
      // Initial bands calculation
      ba[i] = (i % Math.max(1, params.bands)) / Math.max(1, params.bands - 1);
    }

    return { basePositions: basePos, phases: ph, hues: hu, bands: ba };
  }, [params.density, params.bands]); 

  // Material creation
  const material = useMemo(() => {
      return createFishMaterial(params);
  }, [params.palette]); 

  // Ripple Color based on Palette
  const rippleColor = useMemo(() => {
    switch (params.palette) {
      case 'neon': return new THREE.Color('#ff2a9d'); // Magenta/Pink
      case 'sunset': return new THREE.Color('#ffaa00'); // Gold
      case 'cyber': return new THREE.Color('#44ff22'); // Toxic Green
      case 'cherry': return new THREE.Color('#ff99aa'); // Pink
      case 'spectral': return new THREE.Color('#88ffff'); // Light Blue/White
      case 'plasma': return new THREE.Color('#8a2be2'); // Violet
      case 'golden': return new THREE.Color('#ffd700'); // Gold
      case 'frozen': return new THREE.Color('#e0ffff'); // Light Cyan
      default: return new THREE.Color('#44eeff'); // Cyan/Blue
    }
  }, [params.palette]);

  // --- Effects ---

  // Update Attribute: Bands
  useLayoutEffect(() => {
    if (!meshRef.current) return;

    const newBands = new Float32Array(params.density);
    for(let i = 0; i < params.density; i++) {
      newBands[i] = (i % Math.max(1, params.bands)) / Math.max(1, params.bands - 1);
    }

    meshRef.current.geometry.setAttribute(
      'instanceBand',
      new THREE.InstancedBufferAttribute(newBands, 1)
    );
    meshRef.current.geometry.attributes.instanceBand.needsUpdate = true;

  }, [params.bands, params.density]);


  // Initial Attribute Setup
  useLayoutEffect(() => {
    if (meshRef.current) {
      meshRef.current.geometry.setAttribute('instancePhase', new THREE.InstancedBufferAttribute(phases, 1));
      meshRef.current.geometry.setAttribute('instanceHue', new THREE.InstancedBufferAttribute(hues, 1));
    }
  }, [phases, hues]);


  // Update Uniforms
  useEffect(() => {
    if (meshRef.current && meshRef.current.material) {
      const mat = meshRef.current.material as THREE.MeshStandardMaterial;
      if (mat.userData.shader) {
        const u = mat.userData.shader.uniforms;
        u.uTailAmp.value = params.tailAmp;
        u.uTailFreq.value = params.tailFreq;
        u.uBands.value = Math.max(1, params.bands);
        u.uJitter.value = params.jitter;
        u.uSpeed.value = params.speed;

        // Map palette enum to index
        let pIdx = 0;
        switch(params.palette) {
            case 'neon': pIdx = 1; break;
            case 'sunset': pIdx = 2; break;
            case 'cyber': pIdx = 3; break;
            case 'cherry': pIdx = 4; break;
            case 'spectral': pIdx = 5; break;
            case 'plasma': pIdx = 6; break;
            case 'golden': pIdx = 7; break;
            case 'frozen': pIdx = 8; break;
        }
        u.uPalette.value = pIdx;
      }
    }
    // Update Ripple Color
    if (rippleMatRef.current) {
      rippleMatRef.current.uniforms.uColor.value = rippleColor;
    }
  }, [params.tailAmp, params.tailFreq, params.bands, params.jitter, params.palette, params.speed, rippleColor]);


  // --- Animation Loop ---

  const dummy = useMemo(() => new THREE.Object3D(), []);
  const lookAheadV = useMemo(() => new THREE.Vector3(), []);
  const upV = useMemo(() => new THREE.Vector3(0, 1, 0), []);

  // We use a dynamic plane for interaction that faces the camera
  const interactionPlane = useMemo(() => new THREE.Plane(), []);
  const planeNormal = useMemo(() => new THREE.Vector3(), []);
  const targetPoint = useMemo(() => new THREE.Vector3(), []);

  // Interaction state
  const interactionTarget = useRef(new THREE.Vector3(0, -100, 0));

  useFrame((state) => {
    if (!meshRef.current) return;

    const t = state.clock.getElapsedTime();
    const dt = 0.02; 

    // 1. Update Ripple Uniforms
    if (rippleMatRef.current) {
        rippleMatRef.current.uniforms.uTime.value = t;
    }

    // 2. Breathing Effect: Scale whole school gently
    // +/- 1% scale over a slow period
    const breathing = 1.0 + Math.sin(t * 0.8) * 0.01;
    meshRef.current.scale.setScalar(breathing);

    // 3. Update Fish Uniforms
    const mat = meshRef.current.material as THREE.MeshStandardMaterial;
    if (mat.userData.shader) {
      mat.userData.shader.uniforms.uTime.value = t * params.speed;

      // --- Interaction Logic (Desktop vs VR) ---
      let hasInteraction = false;
      let targetPos = new THREE.Vector3();

      if (isPresent) {
        // --- VR MODE ---
        // Find a controller or hand
        // We prefer the Right controller/hand for interaction
        const inputSource = controllers.find(c => c.inputSource.handedness === 'right') || controllers[0];

        if (inputSource && inputSource.controller) {
            // Get tip position
            targetPos.copy(inputSource.controller.position);
            hasInteraction = true;

            // Update VR Hand Visual
            if (handVisualRef.current) {
                handVisualRef.current.visible = true;
                handVisualRef.current.position.copy(targetPos);
            }
        } else {
            if (handVisualRef.current) handVisualRef.current.visible = false;
        }
      } else {
        // --- DESKTOP MODE ---
        if (handVisualRef.current) handVisualRef.current.visible = false;

        // Raycast from camera
        raycaster.setFromCamera(pointer, camera);
        camera.getWorldDirection(planeNormal);
        interactionPlane.setFromNormalAndCoplanarPoint(planeNormal, new THREE.Vector3(0,0,0));

        if (raycaster.ray.intersectPlane(interactionPlane, targetPos)) {
             hasInteraction = true;
        }
      }

      // Process Interaction
      if (hasInteraction) {
        // LERP the global interaction target for smoothness
        interactionTarget.current.lerp(targetPos, 0.15);

        // Update Shader
        const currentMouse = mat.userData.shader.uniforms.uMouse.value as THREE.Vector3;
        currentMouse.copy(interactionTarget.current);

        // Update Visual Ripple (Used in Desktop mostly, or as a spatial marker in VR)
        if (rippleRef.current) {
            rippleRef.current.position.copy(interactionTarget.current);
            rippleRef.current.lookAt(camera.position);
        }
      }
    }

    // 4. Update Instances
    const count = params.density;

    for (let i = 0; i < count; i++) {
      const p = evalPosition(i, t, basePositions[i], params.mode, { speed: params.speed, vertical: params.vertical, density: count });
      const f = evalPosition(i, t + dt, basePositions[i], params.mode, { speed: params.speed, vertical: params.vertical, density: count });

      const dir = lookAheadV.subVectors(f, p);
      if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1);
      dir.normalize();

      dummy.position.copy(p);
      dummy.lookAt(p.clone().add(dir));
      dummy.rotateY(Math.PI); 

      const side = new THREE.Vector3().crossVectors(dir, upV).length();
      dummy.rotateZ((Math.random() * 0.04 - 0.02) + side * 0.1);

      // Apply Individual Fish Scale
      dummy.scale.setScalar(params.fishScale);

      dummy.updateMatrix();
      meshRef.current.setMatrixAt(i, dummy.matrix);
    }

    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <>
      <instancedMesh
        ref={meshRef}
        args={[geometry, material, params.density]}
        castShadow={false}
        receiveShadow={false}
        frustumCulled={false}
      />

      {/* Ripple Mesh (2D Overlay for interaction feedback) */}
      <mesh ref={rippleRef} renderOrder={10}>
        <planeGeometry args={[12, 12]} />
        <shaderMaterial
            ref={rippleMatRef}
            vertexShader={RIPPLE_VERTEX}
            fragmentShader={RIPPLE_FRAGMENT}
            uniforms={{
                uTime: { value: 0 },
                uColor: { value: rippleColor },
            }}
            transparent={true}
            depthWrite={false}
            blending={THREE.AdditiveBlending}
            side={THREE.DoubleSide}
        />
      </mesh>

      {/* VR Hand Visualizer - A glowing orb at controller tip */}
      <mesh ref={handVisualRef} visible={false}>
         <sphereGeometry args={[0.2, 16, 16]} />
         <meshBasicMaterial color={rippleColor} transparent opacity={0.5} />
         <pointLight color={rippleColor} intensity={2} distance={5} />
      </mesh>
    </>
  );
};

export default FishSchool;

import * as THREE from 'three';

function mergeGeometriesSimple(geos: THREE.BufferGeometry[]): THREE.BufferGeometry {
  const positions: Float32Array[] = [];
  const normals: Float32Array[] = [];

  for (const g of geos) {
    const gg = g.index ? g.toNonIndexed() : g;
    const posAttr = gg.getAttribute('position');
    const normAttr = gg.getAttribute('normal');

    if (posAttr) positions.push(posAttr.array as Float32Array);
    if (normAttr) normals.push(normAttr.array as Float32Array);
  }

  const totalPos = positions.reduce((n, a) => n + a.length, 0);
  const mergedPos = new Float32Array(totalPos);
  const mergedNorm = new Float32Array(totalPos);

  let offset = 0;
  for (let i = 0; i < positions.length; i++) {
    mergedPos.set(positions[i], offset);
    if (normals[i]) mergedNorm.set(normals[i], offset);
    offset += positions[i].length;
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(mergedPos, 3));
  geo.setAttribute('normal', new THREE.Float32BufferAttribute(mergedNorm, 3));

  return geo;
}

export function buildFishGeometry(): THREE.BufferGeometry {
  // 1. Advanced Hydrodynamic Body - Fusiform Shape
  // High segment count for smooth liquid reflection
  const body = new THREE.SphereGeometry(1, 64, 64); 
  const pos = body.attributes.position;
  const vec = new THREE.Vector3();

  // Elongated for speed
  const len = 4.2; 

  for(let i = 0; i < pos.count; i++){
    vec.fromBufferAttribute(pos, i);

    // t is normalized Z (-1 to 1)
    const t = vec.z;

    let yFactor = 1.0;
    let xFactor = 1.0;

    if (t > 0) {
       // HEAD SECTION (t: 0 -> 1)
       // Parabolic/Bullet nose for hydrodynamics
       yFactor = Math.pow(1.0 - Math.pow(t, 2.5), 0.5);

       // Slightly narrower width for streamlined entry
       xFactor = yFactor * 0.45;

       // Subtle Operculum (Gill cover) indentation
       if(t > 0.2 && t < 0.35) {
          xFactor *= 0.96;
          yFactor *= 0.98;
       }

       // Mouth detail
       if(t > 0.96) {
           vec.z -= (t - 0.96) * 0.3; // Slight underbite
           if(vec.y < 0) vec.y *= 0.8; 
       }

    } else {
       // BODY & TAIL SECTION (t: 0 -> -1)
       const absT = Math.abs(t);

       // Fusiform Taper: Thicker towards front, long smooth taper to tail
       // Uses cosine-like falloff for natural muscle distribution
       yFactor = Math.cos(absT * 1.57 * 0.9); // Does not go to 0 completely

       // Aggressive narrowing for the peduncle (tail stalk)
       if (absT > 0.5) {
           const tailT = (absT - 0.5) / 0.5;
           yFactor *= (1.0 - tailT * 0.65); // Significant thinning
       }

       // Ensure minimum thickness for peduncle integrity
       yFactor = Math.max(0.08, yFactor);

       // Cross-section: Oval/Elliptical, more compressed at tail
       xFactor = yFactor * 0.4;
    }

    // Asymmetry: Flatter belly, arched back
    if(vec.y < 0) {
        vec.y *= 0.9; 
    }
    if(vec.y > 0) {
        vec.y *= 1.1;
    }

    // Apply scaling
    vec.x *= xFactor;
    vec.y *= yFactor;
    vec.z *= len * 0.5; 

    pos.setXYZ(i, vec.x, vec.y, vec.z);
  }
  body.computeVertexNormals();

  // 2. Fins - Integrated & Swept Back
  const extrudeSettings = {
    depth: 0.03,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.015,
    bevelSegments: 2,
    steps: 1
  };

  // Caudal Fin (Tail) - High Aspect Ratio Lunate
  const tailShape = new THREE.Shape();
  tailShape.moveTo(0, 0);
  tailShape.bezierCurveTo(0.1, 0.2, 0.8, 1.5, 1.8, 2.2); // Upper Leading
  tailShape.lineTo(1.4, 0.5); // Upper Trailing cut
  tailShape.lineTo(1.4, -0.5); // Lower Trailing cut
  tailShape.lineTo(1.8, -2.2); // Lower Tip
  tailShape.bezierCurveTo(0.8, -1.5, 0.1, -0.2, 0, 0); // Lower Leading

  const tail = new THREE.ExtrudeGeometry(tailShape, { ...extrudeSettings, depth: 0.02 });
  tail.rotateY(Math.PI / 2);
  tail.translate(0, 0, -len * 0.5 + 0.1); 

  // Dorsal Fin (Back) - Swept
  const dorsalShape = new THREE.Shape();
  dorsalShape.moveTo(0, 0);
  dorsalShape.quadraticCurveTo(0.5, 0.8, 1.5, 0.9); 
  dorsalShape.quadraticCurveTo(1.0, 0.2, 0.6, 0); 

  const dorsal = new THREE.ExtrudeGeometry(dorsalShape, extrudeSettings);
  dorsal.rotateY(Math.PI / 2);
  dorsal.translate(0, 0.45, 0.2); 

  // Pectoral Fins - Hydrofoils
  const pecShape = new THREE.Shape();
  pecShape.moveTo(0, 0);
  pecShape.quadraticCurveTo(0.2, 0.0, 1.5, -0.4); 
  pecShape.lineTo(0.5, -0.5);
  pecShape.lineTo(0, 0);

  const pecL = new THREE.ExtrudeGeometry(pecShape, extrudeSettings);
  pecL.rotateY(-0.3);
  pecL.rotateX(Math.PI / 2 + 0.2);
  pecL.translate(0.25, -0.15, 0.9);

  const pecR = pecL.clone();
  pecR.applyMatrix4(new THREE.Matrix4().makeScale(-1, 1, 1));

  // Pelvic & Anal Fins (Small stabilizers)
  const pelvShape = new THREE.Shape();
  pelvShape.moveTo(0,0);
  pelvShape.lineTo(0.3, -0.4);
  pelvShape.lineTo(0.1, 0);

  const pelvL = new THREE.ExtrudeGeometry(pelvShape, { ...extrudeSettings, depth: 0.02 });
  pelvL.rotateY(0.1);
  pelvL.rotateX(Math.PI / 2);
  pelvL.translate(0.05, -0.38, 0.6);

  const pelvR = pelvL.clone();
  pelvR.applyMatrix4(new THREE.Matrix4().makeScale(-1,1,1));

  const analShape = new THREE.Shape();
  analShape.moveTo(0,0);
  analShape.lineTo(0.6, -0.4);
  analShape.lineTo(0.3, 0);

  const anal = new THREE.ExtrudeGeometry(analShape, extrudeSettings);
  anal.rotateY(Math.PI / 2);
  anal.translate(0, -0.22, -1.2);

  // --- Eyes ---
  const eyeRadius = 0.08;
  const scleraGeo = new THREE.SphereGeometry(eyeRadius, 16, 16);
  const pupilGeo = new THREE.SphereGeometry(eyeRadius * 0.6, 16, 16);
  pupilGeo.translate(0, 0, eyeRadius * 0.8); 

  const eyePosZ = 1.3; // Further forward on new long body
  const eyePosY = 0.12;
  const eyePosX = 0.18; // Narrower head

  const eyeL_Sclera = scleraGeo.clone();
  const eyeL_Pupil = pupilGeo.clone();
  eyeL_Sclera.scale(1, 0.9, 0.8);
  eyeL_Pupil.scale(1, 0.9, 0.5);

  const matL = new THREE.Matrix4().makeTranslation(eyePosX, eyePosY, eyePosZ);
  eyeL_Sclera.applyMatrix4(matL);
  eyeL_Pupil.applyMatrix4(matL);

  const eyeR_Sclera = scleraGeo.clone();
  const eyeR_Pupil = pupilGeo.clone();
  eyeR_Sclera.scale(1, 0.9, 0.8);
  eyeR_Pupil.scale(1, 0.9, 0.5);

  const matR = new THREE.Matrix4().makeTranslation(-eyePosX, eyePosY, eyePosZ);
  eyeR_Sclera.applyMatrix4(matR);
  eyeR_Pupil.applyMatrix4(matR);

  // Merge
  const fish = mergeGeometriesSimple([
    body, tail, dorsal, pecL, pecR, pelvL, pelvR, anal, 
    eyeL_Sclera, eyeL_Pupil, eyeR_Sclera, eyeR_Pupil
  ]);

  [body, tail, dorsal, pecL, pecR, pelvL, pelvR, anal, 
   eyeL_Sclera, eyeL_Pupil, eyeR_Sclera, eyeR_Pupil, scleraGeo, pupilGeo
  ].forEach(g => g.dispose());

  return fish;
}

