/**
 * Low-poly, sharp, geometric fish model.
 * Uses cones and flat-shaded geometry for a "Cyber/Origami" aesthetic.
 * Design for comparison with organic shape.
 */
function buildGeometricFish(): THREE.BufferGeometry {
    // Main fuselage: A hexagonal cylinder tapered at both ends
    // Length roughly 4.0

    // Front body (Head to mid)
    const frontBody = new THREE.CylinderGeometry(0.35, 0.05, 1.5, 5); // 5 sides for pentagonal stealth look
    frontBody.rotateX(Math.PI / 2);
    frontBody.translate(0, 0, 1.2); // Move to +Z

    // Rear body (Mid to tail)
    const rearBody = new THREE.CylinderGeometry(0.1, 0.35, 2.5, 5);
    rearBody.rotateX(Math.PI / 2);
    rearBody.translate(0, 0, -0.8);

    // Tail Fin: Sharp Triangle
    const tailShape = new THREE.Shape();
    tailShape.moveTo(0,0);
    tailShape.lineTo(0.8, 1.5);
    tailShape.lineTo(-0.2, 0); // V notch
    tailShape.lineTo(0.8, -1.5);

    const extrudeSettings = { depth: 0.1, bevelEnabled: false };
    const tail = new THREE.ExtrudeGeometry(tailShape, extrudeSettings);
    tail.rotateY(Math.PI / 2);
    tail.translate(0, 0, -2.1);

    // Dorsal Fin: Angular
    const dorsalShape = new THREE.Shape();
    dorsalShape.moveTo(0,0);
    dorsalShape.lineTo(1.2, 0.8);
    dorsalShape.lineTo(0.4, 0);
    const dorsal = new THREE.ExtrudeGeometry(dorsalShape, extrudeSettings);
    dorsal.rotateY(Math.PI / 2);
    dorsal.translate(0, 0.3, 0.0);

    // Pectoral Fins: Delta wings
    const wingShape = new THREE.Shape();
    wingShape.moveTo(0,0);
    wingShape.lineTo(1.0, -0.6);
    wingShape.lineTo(0.2, -0.2);

    const wingL = new THREE.ExtrudeGeometry(wingShape, extrudeSettings);
    wingL.rotateY(-0.5);
    wingL.rotateX(Math.PI / 2);
    wingL.translate(0.3, 0, 0.8);

    const wingR = wingL.clone();
    wingR.applyMatrix4(new THREE.Matrix4().makeScale(-1, 1, 1));

    // Eyes: Glowing prisms
    const eyeGeo = new THREE.IcosahedronGeometry(0.12, 0);
    const eyeL = eyeGeo.clone();
    eyeL.translate(0.25, 0.1, 1.3);
    const eyeR = eyeGeo.clone();
    eyeR.translate(-0.25, 0.1, 1.3);

    const fish = mergeGeometriesSimple([
        frontBody, rearBody, tail, dorsal, wingL, wingR, eyeL, eyeR
    ]);

    [frontBody, rearBody, tail, dorsal, wingL, wingR, eyeL, eyeR, eyeGeo].forEach(g => g.dispose());

    return fish;
}

export function buildFishGeometry(type: GeometryType = 'organic'): THREE.BufferGeometry {
    if (type === 'geometric') {
        return buildGeometricFish();
    }
    return buildOrganicFish();
}

import React, { useRef, useMemo, useLayoutEffect, useEffect } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
