interface FishSchoolProps {
  params: SimulationParams;
}

// --- Ripple Shader Material ---
const RIPPLE_VERTEX = `
  varying vec2 vUv;
  void main() {
    vUv = uv;
    gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`;

const RIPPLE_FRAGMENT = `
  uniform float uTime;
  uniform vec3 uColor;
  varying vec2 vUv;

  void main() {
    vec2 center = vec2(0.5);
    float dist = distance(vUv, center);

    // 1. Primary Interference Pattern (High Frequency)
    // Simulates digital/holographic ripples
    float wave1 = sin(dist * 50.0 - uTime * 5.0);
    wave1 = smoothstep(0.9, 0.95, wave1); // Sharpen to thin lines

    // 2. Secondary Wave (Low Frequency) for organic feel
    float wave2 = sin(dist * 20.0 - uTime * 3.0);

    // 3. Caustic/sparkle effect
    float sparkle = sin(dist * 80.0 + uTime * 8.0) * 0.5 + 0.5;

    // 4. Radial Mask (Soft fade out)
    float mask = 1.0 - smoothstep(0.0, 0.5, dist);

    // Combine
    float combined = (wave1 * 0.6 + wave2 * 0.2 + sparkle * 0.1) * mask;

    // Pulse intensity (Breathing effect)
    float pulse = 0.6 + 0.2 * sin(uTime * 2.0);

    // Mix color with white highlights on peaks
    vec3 finalColor = mix(uColor, vec3(1.0), wave1 * 0.6);

    gl_FragColor = vec4(finalColor, combined * pulse * 0.6); // Subtly transparent
  }
`;

const FishSchool: React.FC<FishSchoolProps> = ({ params }) => {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const rippleRef = useRef<THREE.Mesh>(null);
  const rippleMatRef = useRef<THREE.ShaderMaterial>(null);
  const handVisualRef = useRef<THREE.Mesh>(null);

  const { raycaster, pointer, camera } = useThree();
  const { isPresent, controllers } = useXR(); // WebXR Hooks

  // Rebuild geometry when type changes
  const geometry = useMemo(() => buildFishGeometry(params.geometry), [params.geometry]);

  // Prepare Base Positions & Attributes
  const { basePositions, phases, hues, bands } = useMemo(() => {
    const count = params.density;
    const basePos = new Array(count);
    const ph = new Float32Array(count);
    const hu = new Float32Array(count);
    const ba = new Float32Array(count);

    for (let i = 0; i < count; i++) {
      // Random Base Pos
      const px = Math.random() * 40 - 20;
      const py = Math.random() * 10 + 1.5;
      const pz = Math.random() * 40 - 20;
      basePos[i] = new THREE.Vector3(px, py, pz);

      // Attributes
      ph[i] = Math.random() * Math.PI * 2.0;
      hu[i] = Math.random();
      // Initial bands calculation
      ba[i] = (i % Math.max(1, params.bands)) / Math.max(1, params.bands - 1);
    }

    return { basePositions: basePos, phases: ph, hues: hu, bands: ba };
  }, [params.density, params.bands]); 

  // Material creation
  const material = useMemo(() => {
      return createFishMaterial(params);
  }, [params.palette]); 

  // Ripple Color based on Palette
  const rippleColor = useMemo(() => {
    switch (params.palette) {
      case 'neon': return new THREE.Color('#ff2a9d'); // Magenta/Pink
      case 'sunset': return new THREE.Color('#ffaa00'); // Gold
      case 'cyber': return new THREE.Color('#44ff22'); // Toxic Green
      case 'cherry': return new THREE.Color('#ff99aa'); // Pink
      case 'spectral': return new THREE.Color('#88ffff'); // Light Blue/White
      case 'plasma': return new THREE.Color('#8a2be2'); // Violet
      case 'golden': return new THREE.Color('#ffd700'); // Gold
      case 'frozen': return new THREE.Color('#e0ffff'); // Light Cyan
      default: return new THREE.Color('#44eeff'); // Cyan/Blue
    }
  }, [params.palette]);

  // --- Effects ---

  // Update Attribute: Bands
  useLayoutEffect(() => {
    if (!meshRef.current) return;

    const newBands = new Float32Array(params.density);
    for(let i = 0; i < params.density; i++) {
      newBands[i] = (i % Math.max(1, params.bands)) / Math.max(1, params.bands - 1);
    }

    meshRef.current.geometry.setAttribute(
      'instanceBand',
      new THREE.InstancedBufferAttribute(newBands, 1)
    );
    meshRef.current.geometry.attributes.instanceBand.needsUpdate = true;

  }, [params.bands, params.density]);


  // Initial Attribute Setup
  useLayoutEffect(() => {
    if (meshRef.current) {
      meshRef.current.geometry.setAttribute('instancePhase', new THREE.InstancedBufferAttribute(phases, 1));
      meshRef.current.geometry.setAttribute('instanceHue', new THREE.InstancedBufferAttribute(hues, 1));
    }
  }, [phases, hues, geometry]); // Added geometry dependency to re-bind attrs if geo changes


  // Update Uniforms
  useEffect(() => {
    if (meshRef.current && meshRef.current.material) {
      const mat = meshRef.current.material as THREE.MeshStandardMaterial;
      if (mat.userData.shader) {
        const u = mat.userData.shader.uniforms;
        u.uTailAmp.value = params.tailAmp;
        u.uTailFreq.value = params.tailFreq;
        u.uBands.value = Math.max(1, params.bands);
        u.uJitter.value = params.jitter;
        u.uSpeed.value = params.speed;

        // Map palette enum to index
        let pIdx = 0;
        switch(params.palette) {
            case 'neon': pIdx = 1; break;
            case 'sunset': pIdx = 2; break;
            case 'cyber': pIdx = 3; break;
            case 'cherry': pIdx = 4; break;
            case 'spectral': pIdx = 5; break;
            case 'plasma': pIdx = 6; break;
            case 'golden': pIdx = 7; break;
            case 'frozen': pIdx = 8; break;
        }
        u.uPalette.value = pIdx;
      }
    }
    // Update Ripple Color
    if (rippleMatRef.current) {
      rippleMatRef.current.uniforms.uColor.value = rippleColor;
    }
  }, [params.tailAmp, params.tailFreq, params.bands, params.jitter, params.palette, params.speed, rippleColor]);


  // --- Animation Loop ---

  const dummy = useMemo(() => new THREE.Object3D(), []);
  const lookAheadV = useMemo(() => new THREE.Vector3(), []);
  const upV = useMemo(() => new THREE.Vector3(0, 1, 0), []);

  // We use a dynamic plane for interaction that faces the camera
  const interactionPlane = useMemo(() => new THREE.Plane(), []);
  const planeNormal = useMemo(() => new THREE.Vector3(), []);

  // Interaction state
  const interactionTarget = useRef(new THREE.Vector3(0, -100, 0));

  useFrame((state) => {
    if (!meshRef.current) return;

    const t = state.clock.getElapsedTime();
    const dt = 0.02; 

    // 1. Update Ripple Uniforms
    if (rippleMatRef.current) {
        rippleMatRef.current.uniforms.uTime.value = t;
    }

    // 2. Breathing Effect: Scale whole school gently
    // +/- 1% scale over a slow period
    const breathing = 1.0 + Math.sin(t * 0.8) * 0.01;
    meshRef.current.scale.setScalar(breathing);

    // 3. Update Fish Uniforms
    const mat = meshRef.current.material as THREE.MeshStandardMaterial;
    if (mat.userData.shader) {
      mat.userData.shader.uniforms.uTime.value = t * params.speed;

      // --- Interaction Logic (Desktop vs VR) ---
      let hasInteraction = false;
      let targetPos = new THREE.Vector3();

      if (isPresent) {
        // --- VR MODE ---
        // Find a controller or hand
        // We prefer the Right controller/hand for interaction
        const inputSource = controllers.find(c => c.inputSource.handedness === 'right') || controllers[0];

        if (inputSource && inputSource.controller) {
            // Get tip position
            targetPos.copy(inputSource.controller.position);
            hasInteraction = true;

            // Update VR Hand Visual
            if (handVisualRef.current) {
                handVisualRef.current.visible = true;
                handVisualRef.current.position.copy(targetPos);
            }
        } else {
            if (handVisualRef.current) handVisualRef.current.visible = false;
        }
      } else {
        // --- DESKTOP MODE ---
        if (handVisualRef.current) handVisualRef.current.visible = false;

        // Raycast from camera
        raycaster.setFromCamera(pointer, camera);
        camera.getWorldDirection(planeNormal);
        interactionPlane.setFromNormalAndCoplanarPoint(planeNormal, new THREE.Vector3(0,0,0));

        if (raycaster.ray.intersectPlane(interactionPlane, targetPos)) {
             hasInteraction = true;
        }
      }

      // Process Interaction
      if (hasInteraction) {
        // LERP the global interaction target for smoothness
        interactionTarget.current.lerp(targetPos, 0.15);

        // Update Shader
        const currentMouse = mat.userData.shader.uniforms.uMouse.value as THREE.Vector3;
        currentMouse.copy(interactionTarget.current);

        // Update Visual Ripple (Used in Desktop mostly, or as a spatial marker in VR)
        if (rippleRef.current) {
            rippleRef.current.position.copy(interactionTarget.current);
            rippleRef.current.lookAt(camera.position);
        }
      }
    }

    // 4. Update Instances
    const count = params.density;

    for (let i = 0; i < count; i++) {
      const p = evalPosition(i, t, basePositions[i], params.mode, { speed: params.speed, vertical: params.vertical, density: count });
      const f = evalPosition(i, t + dt, basePositions[i], params.mode, { speed: params.speed, vertical: params.vertical, density: count });

      const dir = lookAheadV.subVectors(f, p);
      if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1);
      dir.normalize();

      dummy.position.copy(p);
      dummy.lookAt(p.clone().add(dir));
      dummy.rotateY(Math.PI); 

      const side = new THREE.Vector3().crossVectors(dir, upV).length();
      dummy.rotateZ((Math.random() * 0.04 - 0.02) + side * 0.1);

      // Apply Individual Fish Scale
      dummy.scale.setScalar(params.fishScale);

      dummy.updateMatrix();
      meshRef.current.setMatrixAt(i, dummy.matrix);
    }

    meshRef.current.instanceMatrix.needsUpdate = true;
  });

  return (
    <>
      <instancedMesh
        ref={meshRef}
        args={[geometry, material, params.density]}
        castShadow={false}
        receiveShadow={false}
        frustumCulled={false}
      />

      {/* Ripple Mesh (2D Overlay for interaction feedback) */}
      <mesh ref={rippleRef} renderOrder={10}>
        <planeGeometry args={[12, 12]} />
        <shaderMaterial
            ref={rippleMatRef}
            vertexShader={RIPPLE_VERTEX}
            fragmentShader={RIPPLE_FRAGMENT}
            uniforms={{
                uTime: { value: 0 },
                uColor: { value: rippleColor },
            }}
            transparent={true}
            depthWrite={false}
            blending={THREE.AdditiveBlending}
            side={THREE.DoubleSide}
        />
      </mesh>

      {/* VR Hand Visualizer - A glowing orb at controller tip */}
      <mesh ref={handVisualRef} visible={false}>
         <sphereGeometry args={[0.2, 16, 16]} />
         <meshBasicMaterial color={rippleColor} transparent opacity={0.5} />
         <pointLight color={rippleColor} intensity={2} distance={5} />
      </mesh>
    </>
  );
};

