          // Random velocity
          boidsVel.current[i*3] = (Math.random() - 0.5) * 0.1;
          boidsVel.current[i*3+1] = (Math.random() - 0.5) * 0.1;
          boidsVel.current[i*3+2] = (Math.random() - 0.5) * 0.1;
      }
  }, [params.density]);


  // Setup Standard Attributes
  useLayoutEffect(() => {
    if (!meshRef.current) return;
